use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_crewRequests: FlightStack::CrewRequests
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_crewRequests(container.api_crewRequests);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(crewRequests: FlightStack::CrewRequests)
{
  put_crewRequests(crewRequests);
}

/// setter for IN DataPort
pub fn put_crewRequests(value: FlightStack::CrewRequests)
{
  *extern_api::IN_crewRequests.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_fdDisposition() -> FlightStack::QualifiedFdAndSyncDisposition
{
  return extern_api::OUT_fdDisposition.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_apDisposition() -> FlightStack::QualifiedApDisposition
{
  return extern_api::OUT_apDisposition.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
